def escudo_do_time(nome):
    """URL do escudo do time pelo nome (ex: 'Vasco' ou 'Vasco da Gama'); None se não achar."""
    if not nome:
        return None
    alvo = nome.strip().lower()
    for t in TIMES_BRASIL:
        if t['nome'].lower() == alvo:
            return t['escudo']
    for t in TIMES_BRASIL:
        n = t['nome'].lower()
        if n in alvo or alvo in n:
            return t['escudo']
    return None
